// llm-wiki: the Markdown pages of a vault (the `wiki/` directory), read from a
// read-only mount. The pages carry OKF front matter (`type`, `title`, `created`,
// `updated`, `tags`). The `raw/` captures are not memory and stay out unless
// `includeRaw` is true. `meta/` is generated by the extension and stays out.

import path from 'node:path';
import { LocalIndex } from '../localindex.mjs';
import { exists, FileCache, isUnavailable, MAX_FILES, walkMarkdown } from '../files.mjs';
import { parseFrontMatter, SourceError, titleFrom } from '../model.mjs';
import { indexAdapter } from './base.mjs';

const LABELS = {
  wiki: 'Wiki pages',
  raw: 'Raw captures',
  'wiki/sources': 'Sources',
  'wiki/concepts': 'Concepts',
  'wiki/entities': 'Entities',
  'wiki/analyses': 'Analyses',
  'wiki/syntheses': 'Syntheses',
  'wiki/requirements': 'Requirements',
  'wiki/skills': 'Skills',
};

export function create(cfg) {
  const root = cfg.path;
  const cache = new FileCache();
  const index = new LocalIndex({
    source: cfg.id,
    ttlMs: (cfg.refreshSeconds ?? 120) * 1000,
    folderLabels: LABELS,
    load: () => loadVault(root, cfg, cache),
  });
  const adapter = indexAdapter({
    id: cfg.id,
    type: 'llmwiki',
    name: cfg.name,
    mode: 'live',
    description: cfg.description ?? 'Pages of the personal llm-wiki vault.',
    index,
    facetDepth: 2,
  });
  adapter.status = () => index.status();
  return adapter;
}

export async function loadVault(root, cfg = {}, cache = new FileCache()) {
  if (!(await exists(path.join(root, 'wiki')))) {
    throw new SourceError('not_mounted', 'The wiki directory of the vault is not mounted.');
  }
  const dirs = cfg.includeRaw ? ['wiki', 'raw'] : ['wiki'];
  const files = [];
  const skipped = { files: 0, directories: 0 };
  for (const dir of dirs) {
    try {
      if (dir === 'raw' && !(await exists(path.join(root, dir)))) continue;
      for (const rel of await walkMarkdown(root, path.join(root, dir), {
        maxFiles: MAX_FILES - files.length,
        onSkip: () => { skipped.directories += 1; },
      })) {
        files.push({ root, relative: rel });
      }
    } catch (error) {
      if (dir === 'wiki' || !isUnavailable(error)) throw error;
      skipped.directories += 1;
    }
  }
  const result = await cache.load(files.filter(({ relative }) => path.basename(relative) !== 'index.md'),
    ({ text, mtime, size, tooLarge }, { relative: rel }) => {
      const name = path.basename(rel);
      const { meta, body } = parseFrontMatter(text);
      const heading = body.match(/^#\s+(.+)$/m)?.[1];
      const folder = path.dirname(rel).split(path.sep).filter((s) => s !== '.');
      const date = meta.updated || meta.created || meta.date || mtime;
      const tags = Array.isArray(meta.tags) ? meta.tags : meta.tags ? [meta.tags] : [];
      return {
        id: rel,
        folder,
        title: meta.title || heading || name.replace(/\.mdx?$/i, ''),
        body: tooLarge ? `(The file has ${size} bytes. The app shows files up to 2 MB.)` : body,
        summary: meta.description || titleFrom(body.replace(/^#.*$/m, ''), 220),
        date: date instanceof Date ? date.toISOString() : String(date),
        dateLabel: meta.updated ? 'updated' : meta.created ? 'created' : meta.date ? 'date' : 'file time',
        kind: meta.type || (name === 'log.md' ? 'log' : 'page'),
        tags,
        scope: folder.join('/'),
        meta: [
          ['Path', rel],
          ...Object.entries(meta).map(([k, v]) => [k, Array.isArray(v) ? v.join(', ') : String(v)]),
          ['File time', mtime.toISOString()],
          ['Size', `${size} bytes`],
        ],
        native: rel,
      };
    }, skipped);
  if (!result.docs.length && (skipped.files || skipped.directories)) throw new Error('No documents loaded.');
  return result;
}
